function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'word needs 1 to 10^5 letters.';
  if (!/^[a-j]+$/.test(word)) return "word may only use the letters 'a' to 'j'.";
  return null;
}

