function wonderfulSubstrings(word) {
  const count = new Array(1024).fill(0);
  count[0] = 1;
  let mask = 0;
  let total = 0;

  for (const ch of word) {
    mask ^= 1 << (ch.charCodeAt(0) - 97);
    total += count[mask];
    for (let bit = 0; bit < 10; bit++) {
      total += count[mask ^ (1 << bit)];
    }
    count[mask]++;
  }
  return total;
}

