function wonderfulSubstrings(word) {
  let answer = 0;
  for (let start = 0; start < word.length; start++) {
    const freq = new Map();
    for (let end = start; end < word.length; end++) {
      freq.set(word[end], (freq.get(word[end]) || 0) + 1);
      const odd = [...freq.values()].filter(c => c % 2 === 1).length;
      if (odd <= 1) answer++;
    }
  }
  return answer;
}

