function generate(rand, size) {
  const letters = 1 + Math.floor(rand() * 10);
  const length = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  let word = '';
  for (let i = 0; i < length; i++) word += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [word];
}
